 function image(i,opt,feature=false){if(!i.image)return '';const stem=i.image.replace(/\.webp$/,'');return `<img src="${asset(stem+'-480.webp',opt)}" srcset="${asset(stem+'-480.webp',opt)} 480w, ${asset(stem+'-960.webp',opt)} 960w, ${asset(stem+'-1536.webp',opt)} 1536w" sizes="${feature?'(max-width: 620px) 90vw, 500px':'(max-width: 620px) 32vw, 400px'}" alt="${e(i.name)}" width="1536" height="1024" ${feature?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;}
