 function contact(p,t){const s=p.site,r=s.restaurant;return `<dl class="lm-info-rows"><div><dt>${e(t.hours)}</dt><dd>${e(C.localize(r.hours,p.lang))}</dd></div><div><dt>${e(t.closed)}</dt><dd>${e(C.localize(r.closed,p.lang))}</dd></div>${r.address?`<div><dt>${e(C.localize(r.location,p.lang))}</dt><dd>${e(typeof r.address==='string'?r.address:[r.address.streetAddress,r.address.postalCode,r.address.addressLocality].filter(Boolean).join(', '))}</dd></div>`:''}<div><dt>${e(t.cover)}</dt><dd>${e(money(r.coverCharge,p))}</dd></div></dl><div class="lm-contact-links">${r.phone?`<a href="tel:${e(r.phone.replace(/[ ()-]/g,''))}">${e(t.call)} · ${e(r.phone)}</a>`:''}${r.email?`<a href="mailto:${e(r.email)}">${e(t.email)}</a>`:''}${r.mapsUrl?`<a href="${e(r.mapsUrl)}" target="_blank" rel="noopener">${e(t.directions)}</a>`:''}${r.reservationUrl?`<a class="lm-primary" href="tel:+393922529406" data-booking>${e(t.reserve)}</a>`:''}${r.landingUrl?`<a href="${e(r.landingUrl)}">${e(t.backSite)}</a>`:''}</div>`;}
 function panel(id,title,body,t,extraClass=''){return `<dialog id="lm-${id}-dialog" class="lm-panel ${extraClass}" aria-labelledby="lm-${id}-title"><header class="lm-dialog-heading"><h2 id="lm-${id}-title">${e(title)}</h2><button type="button" class="lm-close" data-close aria-label="${e(t.close)}">${icon('x')}</button></header><div class="lm-panel-scroll" tabindex="0" role="region" aria-labelledby="lm-${id}-title">${body}</div></dialog>`;}
